check.command:
cd /home/tommy/projects/569-w2-ledger && python -c "import ast,sys; src=open('scripts/checklist_engine.py').read(); tree=ast.parse(src); funcs={n.name:n for n in ast.walk(tree) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}; bad=[]; 
for fname in ('waive','claim','release'):
    fn=funcs.get(fname)
    if fn is None: continue
    for n in ast.walk(fn):
        if isinstance(n, ast.Call) and getattr(n.func,'id',None)=='_append_override_entry': bad.append(fname)
sys.exit(1 if bad else 0)"

